DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated; END IF; IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='service_role') THEN CREATE ROLE service_role BYPASSRLS; END IF; END $$;
CREATE SCHEMA storage; CREATE SCHEMA xtj_private;
CREATE FUNCTION xtj_private.safe_jsonb(text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE STRICT AS $$ BEGIN RETURN $1::jsonb; EXCEPTION WHEN OTHERS THEN RETURN '{}'::jsonb; END $$;
CREATE TABLE public.posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_name text NOT NULL,content text,media_url text,media_type text,actor_key text,visibility text DEFAULT 'public',is_deleted boolean DEFAULT false,is_pinned boolean,pinned_at timestamptz,updated_at timestamptz,created_at timestamptz DEFAULT now(),views integer DEFAULT 0,location_name text,location_province text,location_city text,location_district text,location_level text,ip_province text,ip_city text,ip_region_text text,ip_region_status text,ip_resolved_at timestamptz,ip_lookup_started_at timestamptz,ip_region_error text);
CREATE TABLE public.comments(id uuid,post_id uuid);CREATE TABLE public.likes(id uuid,post_id uuid);
CREATE TABLE storage.objects(bucket_id text,name text,metadata jsonb,UNIQUE(bucket_id,name));
CREATE TABLE public.storage_cleanup_jobs(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,photo_id uuid UNIQUE NOT NULL,bucket text DEFAULT 'uploads',paths jsonb DEFAULT '[]',status text DEFAULT 'pending',attempts integer DEFAULT 0,last_error text,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),completed_at timestamptz,claim_token uuid,lease_until timestamptz);
GRANT USAGE ON SCHEMA storage,xtj_private TO service_role; GRANT ALL ON ALL TABLES IN SCHEMA public,storage TO service_role; GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
